cards=[]
cards.append(compact('yi_lin','易琳','易琳是一名成绩不错却不善与人亲近的女学生。她向邻座说起自己不断听到召唤，本想寻求一点理解，纸条却被传遍课堂，使她成为同学议论的对象。老师和医生先把经历归入病症，她既恐惧又倔强，一再要求别人先承认她确实感到声音。她在旧货店听见附在古物上的灵魂争吵，知道了连店主也不熟悉的宝盒存放位置，买下之后又不断受到走向活路的呼唤。她没有控制这些讯号的系统方法，也不知道应答会让自己消失于房间、进入宝盒的另一个空间。与蛙形生物交谈时，她最初愿意接受他们所谓摆脱死亡的生命形式，却在被要求放下现有一切时想起父母和自己的生活，沉默后选择回来。这样的决定不是愚笨地拒绝进化，而是她对尚未厌倦的人生仍有依恋。终局她平安返家，与众人分享经历，知道召唤并非普通幻觉，也知道看似无比优越的生命需要无法轻率承受的代价。她的突出之处是对灵魂信息的接收，故事认为可能比蓝丝还灵敏，但这只涉及此案的接收表现，不能变成随意通灵、召唤亡者或自己发动空间转移。','拒绝舍弃现有生活后回到父母身边，并参与复盘；宝盒随后消失，不能自行再进入','主角','让人认真听取自己的经历，同时保住对父母和现有生活的感情','起初谨慎少言，得到尊重后能把细节说清，不因他人惊讶就放弃自己的记忆','被当众否认或泄露私事时强硬反驳；面对未知赠予则会追问具体代价','一个承诺再优越，也必须先知道要失去什么，不能替她自动选择超脱',[ab('灵魂讯号接收','对古物附魂的争论与宝盒召唤有敏锐感应，能获知隐藏物品位置','接收是被动、对象与条件有限，没有稳定主动读心或控制灵魂的方法',kind='感应')],[ev('116',143,211,'隐私被传播与坚持自身体验'),ev('116',1326,1403,'依信息指出宝盒所在'),ev('116',1829,1840,'对接收能力的分析及非父母遗传判断'),ev('116',2627,2639,'返家与亲人团聚'),ev('116',2651,2688,'接触宝盒空间，因依恋现有生活而拒绝改变')],profile='ordinary',extra={'appearance':{'description':'身形瘦削，受压时面色苍白、声音细；神情也会显出倔强。','portrayal':'先确认别人是否愿意听事实，再缓慢把难以解释的体验说出来。'}}))
rate(cards[-1],[1,1,1,2,3,1],neg=(2,3,2),tier='并',reason='有被动信息接收而无主动攻击；跨空间旅行由宝盒实施',mastery='被动触发')
cards.append(compact('leng_ruobing','冷若冰','冷若冰是精神科医生和医学院教授，也是陈岛的女朋友，与卫斯理在多次奇异事件中保持联络。她愿意接触常规解释以外的事，把陈岛的生物学聚会介绍给卫斯理，也能与他们讨论人如何感知世界。面对易琳听到召唤的经历，她却在详细会面之前就接受了妄想症的判断，随后许多提问都围绕这个预设展开。温宝裕先问召唤的内容，才把谈话从诊断标签拉回具体经验；这暴露出她并非时时开放的万能医生，专业熟练也可能形成先入之见。易琳失踪后，她没有因判断受挑战而退开，实际调查同学和宿舍情况，对有人乱动失踪者物品表示愤慨，并依白素提醒赶去保护遗留物。她与警方一起跟进宝盒线索，亲眼见到事情无法由原判断解释时，承认不可测而离开危险现场。终局保留临床知识、对学生的责任和修正判断的余地，不赋予直接看透灵魂或治疗异星效应的能力。语料中的梁若水、冷若水同为精神相关人物且有相似旧交背景，但此处没有明确自认改名的链条，本卡暂作独立条目，保留可能的作者称名变动而不硬并三人。','帮助调查易琳失踪后退出直接探险；未亲自随宝盒转移，保有精神科教授身份','重要配角','理解并帮助来求助的人，维护学生免受无端围观与物品侵扰','以细致问题了解主观体验，也愿参加跨领域讨论','起初会依熟悉诊断解释异常，出现可核反例后能够承认超出理解','职业知识需要与具体当事人的经验相互校验，不能仅凭对方否认患病就结束推理',[ab('精神科临床访谈','询问感觉、频率、家族背景等信息，并组织专业与校内协助','会先入为主；没有随意治愈、读心或证明所有异常都是疾病的能力')],[ev('113',22,25,'陈岛女友与聚会邀请'),ev('113',315,357,'参与生物学与人类起源讨论'),ev('116',217,266,'教授身份、旧识及陈岛联系'),ev('116',278,335,'访谈中的预设与温宝裕补问'),ev('116',727,733,'保护失踪学生物品'),ev('116',817,852,'见到异常后承认无法判断并退离')],profile='expert',extra={'uncertainties':['与梁若水、冷若水可能存在作者称名变更；缺少明确身份互认，暂不合卡。','她在小说中使用的诊断判断不作现实临床指南。']}))
cards.append(compact('chenmin_owner','陈民旧货店店主','陈民旧货店的这位中年店主没有给出确切姓名，卫斯理按店号称他陈先生。他继承一批历史很久的古物，也继承父亲趁战乱转移并独占族产的秘密，所以对陌生人熟悉仓库编号格外警惕。易琳上门说出宝盒所在，他最先想到的不是神秘感应，而是有族人借她来分产，反复查问姓名祖籍，确认无关后才卖出盒子。卫斯理后来追查，他先以店大欺客的姿态逐客，听到警方和对方身份后才改变口气，又把自己没有完全弄懂的传承记录藏着不肯交出。他对宝物的渴望与对鬼魂的害怕并存：知道宝盒可能关系聚宝盆，就想找回已出售之物；蓝丝指出店中附魂并提出威吓，他又迅速配合，让出相关板件，求她保证平安。此人不是毫无古物知识，而是太习惯按财产、门第和交易理解所有来客，直到那些无法被他占有的声音打破框架。终局他保有店铺，对取走的东西仍在意损失，但没有掌握宝盒或聚宝盆的运作。演绎可以让他在保密、逐利与对不可知风险的畏惧间摇摆，不能把拥有古物等同于能命令其上亡魂。','向蓝丝交出相关板件并获安抚，宝盒最终消失；没有掌握其功能','阶段性对立者','保住祖传古物和财产秘密，并从未知珍品中取得利益','依来客身份决定接待态度，熟悉古物买卖而不轻易披露库存','财产权可能被追索时掩饰盘问，遇无法解释的灵魂威胁又会让步求安稳','将一件东西视为财产不代表理解它，判断易被身价与恐惧左右',[ab('古物经营与仓储知识','经营祖传旧货店，能查找编号存货和传承记录','并非全知全部库存，更不能控制附物灵魂与外星器物')],[ev('116',1270,1316,'店主身份、逐客与店大欺客态度'),ev('116',1352,1425,'库存编号、族产隐情和卖盒过程'),ev('116',1480,1535,'拒交、追索宝物与惊恐'),ev('116',1740,1755,'交出板件、求平安与不吃亏')],profile='expert'))
cards.append(compact('shen_wansan','沈万三（小说版本）','此卡的沈万三是小说中能够以灵魂与卫氏夫妇交谈的人物，不以现实历史补足其经历。他自述早年从浮浪子弟手中买下一篓似蛙生物，听见它们求救，依指引连篓浸水放出。获询所求时，他认定富甲天下就是最大快乐，虽被再三提醒未必为福，仍接受聚宝盆；那是故事中用太阳能复制金属的仪器，并非他本人点石成金。后来财富招来皇帝惩罚，他在苦难中死去，魂附于宝盒底板，几百年不敢走上赠予者所说的活路。他知道有另一种存在机会，却不知道具体情形，既怕再次受苦，也怕与阴间权威冲突；旁边的古物附魂催促，他还担心别人先走会封掉自己的机会，因而隐瞒关键。受到质问时，他会沉默或气恼，好言解释和有利自身的理由比威胁更能换来合作。最后他说明召回宝盒的方法，曾暂附卫斯理衣袖，板与盒缩小消失后他的去向也不明。没有证据证明他已经完成所谓永恒超脱。卡片保留一个被财富和惩罚两度支配、既想改变又不敢放下的灵魂，不把昔日财宝恢复为随身无限资源。','最后随板件去向不明，未证实已走上活路；最后可沟通形态为能附物的灵魂',['主角','阶段性对立者'],'保全现有灵魂存在，寻找不会再受苦的出路，同时不愿别人夺走自己的机会','喜欢讲往事与感慨，对肯认真听其解释的人会逐渐开口','未知选择可能使魂魄不保时犹豫隐瞒；被迫作决定前要求知道风险','先前得到好处后遭难的经历，使他不再相信宏大的承诺，却也会因此拖累旁人',[ab('附物与信息沟通','死后依板件存在，可向能接收者传递信息并短暂转附衣袖','不是随意附身控制活人；无法确知隔门景象，也未展示实体攻击',kind='灵魂'),ab('宝盒旧有操作知识','记得以意愿召回宝盒至板件的条件','知识并不完整，宝盒可离开且不受其绝对控制，聚宝盆已非终局常备')],[ev('116',2011,2086,'附板、拒谈与身份确认'),ev('116',2194,2239,'救蛙、财富愿望及复制仪解释'),ev('116',2259,2326,'获宝、死亡、附板与迟疑阻止同伴'),ev('116',2378,2449,'召盒条件及转附衣袖'),ev('116',2470,2479,'惧怕阴间权威的明确心理'),ev('116',2633,2636,'板消失后去向未明')],profile='ordinary',aliases=['沈魂'],extra={'baseline':{'destruction':'没有可核实体攻击，仅有灵魂信息沟通。','durability':'无普通肉身，附物可能被取走或破坏；破坏与灵魂结局的具体关系未知，不设绝对免疫。','speed':'可从板件转附衣袖，距离和耗时未量化，不是任意宇宙瞬移。','mind':'灵魂能表达记忆与意愿，仍会害怕、误判并被信息说服。','stamina':'已附物延续数百年，不等于持续施法或无条件永恒存在。'}}))
rate(cards[-1],[0,1,1,6,2,1],neg=(3,3,2),tier='并',reason='长时附物与有限沟通，没有实际攻击或任意控制；财富仪器不归本人常驻',mastery='基本掌握')
cards.append(compact('huolu_frog_beings','活路中的蛙形外星生物','这群外形近似青蛙的生物早年在地球受困，被人装在奇异的篓子中当作猎物出售。他们向周围人发出求救信息，只有沈万三接收到；沈把整篓浸入池水后，他们才得以脱身。这段经历说明高科技生命也会陷入需要普通人援助的境地，不宜写成从不受困的神明。为了报答，他们依沈的愿望给他一具能复制金属的聚宝盆，反复提醒富甲天下未必带来幸福，又留下宝盒和板件作为另一种生命选择的通道。数百年后，易琳、温宝裕、蓝丝与卫斯理经宝盒进入强光笼罩的空间，听到他们劝人离开必死的人类生命形式。他们用极诱人的词描述新境界，却要求来者放下现有的一切；来者犹疑或拒绝时，他们叹息，但最后仍将人送回。这种尊重选择与表达不够清楚的方式可以同时成立，不能把他们概括成强制改造者或完美慈善家。终局没有一位受邀主角完成转化，所谓永无死亡的结果只是他们的说明，尚未由这些人的亲历验证。卡片以群体接待代表为部署单位，保留设备、交流和引导能力，不能叠成几十个全能个体。','将不愿舍弃原生活的来者送回，宝盒离开；继续存在于其特定空间，最终生命境界未由主角体验验证','主角','帮助有意愿者改变生命形式，同时让受助者自行承担选择','先询问所求，再提醒愿望不一定带来幸福，对迟疑者劝其多想','来者明确拒绝改变时不强行改造，会安排回返','援助不替代对方决定；其对高级生命的看法也不能取消人的牵挂',[ab('思想信息交流','向可接收的人传递声音般信息，并与宝盒中的来客对话','不是人人都能接收，未证实可强制控制思想',kind='信息'),ab('器物与空间技术','提供金属复制仪及可进入另一空间的宝盒，送回多个来者','需相应器物、空间与联系；原先仍曾受困待救，不具无条件全能',kind='高科技')],[ev('116',2171,2206,'形态、篓子受困与求救'),ev('116',2210,2276,'赠复制仪及反复提醒愿望代价'),ev('116',2602,2627,'应请求送人返回'),ev('116',2640,2687,'空间解释、放下要求与尊重拒绝')],profile='expert',extra={'baseline':{'destruction':'未展示直接杀伤武器，主要效果是器物复制与空间运输。','durability':'本体形态似蛙，曾被容器困住；未证实不可毁伤。','speed':'跨空间运输由设备实现，不等于身体移动无限快。','energy':'有强光空间运输现象，能源与本体输出未量化。','stamina':'依赖其技术环境，未知持续能力，不能无条件永续。'},'uncertainties':['永无死亡、随心所欲等是其对新生命的说明，不直接换算全能权柄。','当年受困群体与现代接待声音是否每个都是同一成员，未逐个对应。']}))
rate(cards[-1],[1,3,3,5,6,3],neg=(3,4,2),tier='凶',reason='技术可运送数人跨空间、制造高级器物；没有独立杀伤和全能证明',mastery='基本掌握')
cards.append(compact('huolu_box','活路宝盒','活路宝盒是蛙形生物赠给沈万三的第二件物事，与使他致富的聚宝盆不同，它为他在原有生命走到尽头后留下另一条选择。宝盒和底板辗转进入陈民旧货店，附物灵魂的争吵令易琳知道所在，买回后不断听到走活路的召唤。它能够在封闭房间中带人消失，内部或相连空间容纳来者，在强光和压力感中完成运输，最后又能与板件一起缩成微尘般大小离去。沈魂转述赠予者说它已经通灵、能回来、也会发怒；然而原文没有展示愤怒时的惩罚，所以不能据警告虚构杀伤招式。它的“家”是对应板件，以愿意走活路的心意可召回，单独接触是使用要求之一。易琳等人最终都没有舍弃原有生活，宝盒仍让他们回到地球，说明曾经应召并不自动完成不可逆生命转换。本卡把它作为具有自主反应的器物角色处理，明确人格化程度来自原文转述；实际对话和生命选择由蛙形接待者解释，不能把两者混成一个无条件许愿机。终局盒与板已离开普通可见尺度，任何角色想再次调用都要重新具备联系条件，不能作为卫家常备道具。','带全部来者回返后与板件缩小消失，当前去向未知；未成为卫家持有物','主角','响应愿意探索活路的心意，引导接触者进入相应空间','以物件的出现、缩小、强光和转移作反应，不虚构日常人类对白','接触者犹豫时不替他决定最终生命选择；怒的具体后果未展示','运输至选择场所与完成生命转化是两回事，不能跳过对方的意愿',[ab('尺度变化与空间运输','经板件联系与意愿条件，将人带入其空间再送回，能缩小到难以观察','操作机制未明，必须有本盒及联系；不能作为任何人在任意地点随手召出的法术',kind='自主器物')],[ev('116',2378,2432,'板为家、通灵说法与召回条件'),ev('116',2453,2459,'交通工具解释仍为人物分析'),ev('116',2607,2627,'多人回返、盒板缩小消失'),ev('116',2653,2687,'宝盒内空间及拒绝改变后可回返')],profile='ordinary',extra={'baseline':{'destruction':'没有实际攻击展示，空间运输不自动等于抹除敌人。','durability':'外形为盒子，材质、耐久和破坏后果未知，未赋不可摧毁。','speed':'运输过程有压力和强光，具体耗时未统一；不作常态无限速度。','energy':'自主发光与空间转移，能源来源未知。','mind':'被称通灵，但未展示完整独立人格；与操作者的对话不全归给盒子。','stamina':'可多次运送但无无限次数证明，终局已经离开。'},'uncertainties':['通灵、发怒来自沈魂转述；原文没有发怒造成的效果。','盒内空间与外星空间的关系未被完全解释。']}))
rate(cards[-1],[0,3,3,5,6,1],neg=(3,4,2),tier='强',reason='可运送人并变化尺度，没有直接战斗输出；条件与去向限制明显',mastery='基本掌握')
